options.onCreated:
/**
 * pt_header · onCreated — เตรียม helper ให้ content ของการ์ดคนไข้ (D4.4)
 *
 * 🔴 ทุกตัวเป็น "function" ไม่ใช่ค่า snapshot — onCreated รันครั้งเดียว ถ้า copy ค่าจาก formModel
 *    ไว้ตรง ๆ แล้วค่าเปลี่ยนทีหลัง (แม่ยิง setValue เพิ่ม) การ์ดจะไม่ตาม (LLM-VueUI ข้อ 11)
 *    เก็บเป็น arrow function ที่อ่าน field.params สดทุกครั้ง → Vue track dep ให้เอง
 *
 * 🔴 อ่านผ่าน field.params (= getFormRef().formParams) ไม่ใช่ field.formModel
 *    เดิมอ่าน formModel แล้วการ์ดขึ้น "ไม่มีข้อมูลผู้ป่วย" ตลอด — สาเหตุ (verify กับ runtime 2026-08-04):
 *    SdFormRender.buildDataModel() คัดค่าจาก formData เข้า formDataModel เฉพาะ field ที่ `formItemFlag: true`
 *    จอนี้เป็น form_ui ที่มีแต่ vue-ui (formItemFlag: false) ⇒ ไม่มี field ให้ค่าลง
 *    ⇒ field.formModel เหลือแต่ system key (_id/xsitex/xunitx/…) ไม่ว่าปุ่มจะส่ง initData มาครบแค่ไหน
 *    ⇒ ปุ่มฝั่ง EMR จึงส่ง patient context ทาง `params` แทน (emr-drug-order-button.js)
 *
 * 🔴 อ่านผ่าน field.params ไม่ใช่ identifier ตรง ๆ ในเทมเพลต — ให้จุดอ่านอยู่ที่เดียว
 *    ตรงกับที่ scope proxy ให้ params ชนะ state/data อยู่แล้ว (SDCustomContent.buildScopeProxy)
 *
 * 🔴 field lifecycle event ไม่มีตัวแปร event ให้ (userInfo/data/value ใช้ไม่ได้ตรง ๆ)
 *    ต้องใช้ this.globalUserState / this.formParams แทน
 */

const s = this.vueState;
const field = this;

// patient context ทั้งชุดมาทาง params (ดูหัวไฟล์) — computed reactive ของ CoreFieldMixin
// อ่านสดทุกครั้ง ไม่ snapshot: ค่าเปลี่ยนแล้วการ์ดตามเอง
const LAB_WORKLIST_PROCESS_ID = '6a9434c3422c1ca959829d5e';
const formRef = () => field.getFormRef && field.getFormRef();
s.manualContext = null;
s.vnRows = [];
s.vnLoading = false;
s.vnError = '';
s.visitDate = '';
s.selectedVisitId = '';
const m = () => s.manualContext || ((formRef() || {}).$cpoeVisitContext) || field.params || {};

// ค่าที่ต้องแสดงเป็นข้อความ — คืน '' เมื่อไม่มี เพื่อให้ v-if ในเทมเพลตตัดสินได้ตรง ๆ
s.ptText = (key) => {
	const v = m()[key];
	if (v === null || v === undefined || v === '') return '';
	// เผื่อแม่ส่งมาเป็น { value, label } (select-form) — เอา label ให้คนอ่าน
	if (typeof v === 'object' && !Array.isArray(v)) return String(v.label || v.value || '');
	return String(v);
};

s.ptHas = () => !!(s.ptText('full_name') || s.ptText('hn') || s.ptText('visit_id'));

s.ptName = () => s.ptText('full_name') || '(ไม่ทราบชื่อ)';
s.ptInitial = () => {
	const n = s.ptName().trim();
	return n && n !== '(ไม่ทราบชื่อ)' ? n.charAt(0) : '?';
};

// รูปคนไข้ — รับได้ทั้ง url ตรง ๆ และโครง p_pic ของฟอร์ม Person ([{ url }])
s.ptPic = () => {
	const v = m().photo_url || m().p_pic;
	if (!v) return '';
	if (typeof v === 'string') return v;
	if (Array.isArray(v) && v[0] && v[0].url) return v[0].url;
	return '';
};

// "อายุ 25 ปี · หญิง" — รวมเป็นชิปเดียวตาม mockup (สองชิปแยกกินที่โดยไม่ได้ข้อมูลเพิ่ม)
s.ageSexText = () => {
	const age = s.ptText('age');
	const sex = s.ptText('sex');
	return [age ? 'อายุ ' + age : '', sex].filter(Boolean).join(' · ');
};

// ชิปสิทธิ์ ✓OFC ✓UCS — บอกว่าวิสิทนี้ตรวจสอบสิทธิ์อะไรมาแล้วบ้าง (ตัวที่ "ใช้" เลือกที่แถบสิทธิ์ของใบ)
s.insChips = () => {
	const arr = m().inscl_hos;
	if (!Array.isArray(arr)) return [];
	const seen = {};
	const out = [];
	arr.forEach((row) => {
		const code = String(((row || {}).inscl_item_main || {}).value || '');
		if (!code || seen[code]) return;
		seen[code] = true;
		out.push(code);
	});
	return out;
};

// มีข้อมูลร่างกายให้แสดงไหม (น้ำหนัก · ส่วนสูง · BMI · BSA)
// 🔴 ห้ามคิด BMI/BSA เองในจอนี้ — แม่คิดมาแล้วส่งค่ามา (D4.4) คิดซ้ำแล้วสูตรต่างกัน สองจอจะโชว์คนละเลข
s.hasBody = () => !!(s.ptText('weight') || s.ptText('height') || s.ptText('bmi') || s.ptText('bsa'));

/* ── Vital signs ────────────────────────────────────────────────────────────
   🔴 ไม่ฝังเกณฑ์ค่าปกติไว้ในจอสั่งยา (D4.4 · D12 ข้อ 4 ยังไม่เคาะว่าเกณฑ์มาจากไหน)
      รับได้ 2 รูป:
        bp: '120/80'                      → แสดงเฉย ๆ ไม่ทำสี
        bp: { value: '120/80', level: 'warn' } → ทำสีตามระดับที่แม่ส่งมา
      แม่ (หน้า EMR) มี vsRules อยู่แล้วใน opd_card จึงเป็นคนตัดสินระดับ ที่เดียวทั้งระบบ */
const VITALS = [
	{ key: 'bp', label: 'BP', unit: 'mmHg' },
	{ key: 'pr', label: 'PR', unit: '/นาที' },
	{ key: 'temp', label: 'Temp', unit: '°C' },
	{ key: 'rr', label: 'RR', unit: '/นาที' },
];
// ชื่อ class ของ pcard (CSS global ของแอป) — ชุดเดียวกับที่ opd_card ใช้ในหน้า EMR
// 🔴 แม่ (opd_card.vsClass) ส่ง level มาเป็น 'warn'/'bad' — ต้อง map เป็น is-warning/is-danger ที่นี่
//    เขียนชื่อ class ผิด = ค่าที่ผิดปกติจะโชว์เป็นสีปกติ โดยไม่มี error ให้เห็น
const LEVEL_CLASS = { warn: 'is-warning', warning: 'is-warning', bad: 'is-danger', danger: 'is-danger' };

s.vitals = () => {
	const data = m();
	const out = [];
	VITALS.forEach((v) => {
		const raw = data[v.key];
		if (raw === null || raw === undefined || raw === '') return;
		const isObj = typeof raw === 'object' && !Array.isArray(raw);
		const value = isObj ? raw.value : raw;
		if (value === null || value === undefined || value === '') return;
		out.push({
			key: v.key,
			label: v.label,
			unit: v.unit,
			value: String(value),
			cls: (isObj && LEVEL_CLASS[String(raw.level || '').toLowerCase()]) || '',
		});
	});
	return out;
};

// แถบแพ้ยา — allergy_tags เป็น string ที่ api-checkin สร้างไว้ (เช่น "💊 พารา 🔴")
// 🔴 เป็นแค่ป้ายบอก เทียบกับยาไม่ได้ (D8.3 ชั้น 1) → ข้อความท้ายแถบต้องไม่อ่านว่า "ตรวจแล้ว"
s.allergyTags = () => {
	const v = m().allergy_tags;
	if (!v) return [];
	if (Array.isArray(v)) return v.map((x) => String(x)).filter(Boolean);
	return String(v).split(',').map((x) => x.trim()).filter(Boolean);
};

/* ── allergy-tag.snippet · ป้ายแพ้ยา emoji → ไอคอน SVG ของระบบ (2026-10-01) ──────────────
   ต้นฉบับ: sdform/cpoe/allergy-tag.snippet.js — แก้ที่นี่แล้ววางทับทุกจอที่ใช้
     (pt_header ของ Drug Order + Item Order · opd_card ของ EMR · emr_view · patient_history)
   ป้ายใน DB ยังเป็นข้อความ "💊 paracetamol 🔴" (api-checkin · api-tran-update · cpoe-allergy-sync)
   🔴 emoji เป็นแค่รหัสในข้อมูล — จอแปลงเป็นไอคอน + ป้ายระดับ ผู้ใช้ไม่เห็น emoji (พี่เคาะแบบ A 2026-10-01)
      วิสิทเก่าทุกวันเก็บรูปเดียวกัน ⇒ แสดงแบบใหม่ได้ทันทีโดยไม่ต้องย้ายข้อมูล
   🔴 อ่านรหัสไม่ออก = แสดงข้อความตามที่เก็บ ห้ามตัดทิ้ง — ป้ายแพ้ยาหายจากจอ อันตรายกว่าหน้าตาไม่สวย */
const ALG_TYPE = [
	{ mark: '💊', icon: 'addon-capsule-pill', label: 'แพ้ยา' },
	{ mark: '🍤', icon: 'el-food', label: 'แพ้อาหาร' },
	// ⚠️ มี 2 รูปในข้อมูลจริงได้ (มี/ไม่มี variation selector U+FE0F) — ตัวยาวต้องเช็คก่อน
	{ mark: '⚠️', icon: 'el-warning', label: 'อื่น ๆ / ภาวะของผู้ป่วย' },
	{ mark: '⚠', icon: 'el-warning', label: 'อื่น ๆ / ภาวะของผู้ป่วย' },
];
// key = class ของ .pcard-sev ใน initcraft/src/styles/index.scss (ไม่มี class = สีแดง) · tag = type ของ el-tag
const ALG_LVL = [
	{ mark: '🔴', key: 'severe', label: 'รุนแรง', tag: 'danger' },
	{ mark: '🟠', key: 'moderate', label: 'ปานกลาง', tag: 'warning' },
	{ mark: '🟡', key: 'mild', label: 'เล็กน้อย', tag: 'info' },
];
s.algOf = (raw) => {
	let text = String(raw == null ? '' : raw).trim();
	const type = ALG_TYPE.find((t) => text === t.mark || text.startsWith(t.mark + ' '));
	if (type) text = text.slice(type.mark.length).trim();
	const lvl = ALG_LVL.find((l) => text.endsWith(' ' + l.mark));
	if (lvl) text = text.slice(0, -lvl.mark.length).trim();
	return {
		name: text,
		icon: type ? type.icon : 'el-warning',
		title: (type ? type.label : 'แพ้') + (lvl ? ' · ระดับ' + lvl.label : ''),
		sev: lvl ? lvl.key : '',
		sevLabel: lvl ? lvl.label : '',
		tagType: lvl ? lvl.tag : 'danger',
	};
};
s.algList = (tags) => (Array.isArray(tags) ? tags : tags ? [tags] : []).map(s.algOf).filter((a) => a.name);
/* ── end allergy-tag.snippet ── */


/* Visit picker shared by LAB and X-ray launchers. */
s.manualMode = () => !!((field.params || {}).manual_visit);
s.visitPatient = visit => (visit && visit.pid) || {};
s.visitName = visit => {
  const p = s.visitPatient(visit);
  const pre = p.prename && typeof p.prename === 'object' ? (p.prename.label || p.prename.value) : p.prename;
  return [pre || '', p.p_fname || '', p.p_lname || ''].join(' ').replace(/\s+/g, ' ').trim();
};
s.visitContext = visit => {
  const p = s.visitPatient(visit);
  const unit = (visit && (visit.current_unit || visit.unit_to)) || null;
  return {
    person_id: String((visit && visit.xtbxlv1_xfx_id) || p.value || ''),
    hn: p.hn || '', full_name: s.visitName(visit),
    sex: ({'1':'ชาย','2':'หญิง'})[String(p.p_gender || '')] || String(p.p_gender || ''),
    age: p.age == null ? '' : p.age, blood_group: p.p_abogroup || '',
    p_pic: Array.isArray(p.p_pic) ? p.p_pic : null,
    allergy_tags: Array.isArray(visit && visit.allergy_tags) ? visit.allergy_tags : [],
    visit_id: String((visit && (visit._id || visit.value)) || ''),
    visit_tran_id: String((visit && (visit.visit_tran_id || visit.tran_id || visit.vtran_id)) || ''),
    visit_tran_count: Number((visit && visit.visit_tran_count) || 0),
    visit_tran_ambiguous: !!(visit && visit.visit_tran_ambiguous),
    current_unit: unit,
    current_room: (visit && (visit.current_room || visit.room_to)) || null,
    visit_tran_status: String((visit && visit.visit_tran_status) || ''),
    visit_priority: String((visit && visit.visit_priority) || '10'),
    vn: (visit && visit.vn) || '',
    visit_type: (visit && visit.visit_type && (visit.visit_type.label || visit.visit_type.value)) || (visit && visit.visit_type) || '',
    visit_datetime: (visit && (visit.visit_date || visit.created_at)) || '',
    visit_clinic: (visit && visit.visit_clinic && (visit.visit_clinic.label || visit.visit_clinic.value)) || (visit && visit.visit_clinic) || '',
    visit_doctor: (visit && visit.visit_doctor && (visit.visit_doctor.label || visit.visit_doctor.value)) || (visit && visit.visit_doctor) || '',
    dx_summary: '', service_type: '',
    inscl_hos: Array.isArray(visit && visit.inscl_hos) ? visit.inscl_hos : []
  };
};
s.selectVisit = visit => {
  const ctx = s.visitContext(visit);
  if(!ctx.visit_id) return;
  s.selectedVisitId = ctx.visit_id; s.manualContext = ctx;
  const form = formRef(); if(form) form.$cpoeVisitContext = ctx;
  const orderField = field.getFieldRef && field.getFieldRef('item_screen');
  if(orderField && orderField.vueState && typeof orderField.vueState.setPatientContext === 'function') orderField.vueState.setPatientContext(ctx);
};
s.selectVisitById = id => {
  const key = String(id || ''); s.selectedVisitId = key;
  if(!key){
    s.manualContext = null;
    const form = formRef(); if(form) form.$cpoeVisitContext = null;
    const orderField = field.getFieldRef && field.getFieldRef('item_screen');
    if(orderField && orderField.vueState && typeof orderField.vueState.setPatientContext === 'function') orderField.vueState.setPatientContext(null);
    return;
  }
  const visit = s.vnRows.find(row => String((row && row._id) || '') === key);
  if(visit) s.selectVisit(visit);
};
s.visitThaiDate = visit => {
  const raw = String((visit && (visit.visit_date || visit.created_at)) || '');
  const hit = raw.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/); if(!hit) return '';
  const months = ['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน','กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'];
  return Number(hit[3]) + ' ' + months[Number(hit[2]) - 1] + ' ' + (Number(hit[1]) + 543);
};
s.visitOptionLabel = visit => ['HN' + (s.visitPatient(visit).hn || '–'), 'VN' + ((visit && visit.vn) || '–'), s.visitThaiDate(visit), s.visitName(visit) || 'ไม่ทราบชื่อ'].filter(Boolean).join(' · ');
s.extractVisitPayload = out => {
  const rows = [out, out && out.data, out && out.data && out.data.data, out && out.reply && out.reply.data];
  for(let i=0;i<rows.length;i++) if(rows[i] && Array.isArray(rows[i].visits)) return rows[i];
  return null;
};
s.loadTodayVisits = () => {
  if(s.vnLoading) return;
  const form = formRef(), api = field.globalUserState || (form && form.userState);
  if(!api || typeof api.runProcess !== 'function'){ s.vnError = 'ไม่พบตัวเชื่อมข้อมูล Visit'; return; }
  s.vnLoading = true; s.vnError = '';
  const p = field.params || {};
  api.runProcess(LAB_WORKLIST_PROCESS_ID, { action:'list_open_visits', organization_code:String(p.organization_code || '') }, out => {
    s.vnLoading = false;
    const payload = s.extractVisitPayload(out);
    if(!payload){ s.vnRows = []; s.vnError = 'รูปแบบข้อมูล Visit ไม่ถูกต้อง'; return; }
    s.vnRows = Array.isArray(payload.visits) ? payload.visits : [];
    s.visitDate = String(payload.visit_date || '');
    if(!s.vnRows.length) s.vnError = 'วันนี้ยังไม่มีผู้ป่วยที่เปิด Visit อยู่';
    const originalId = String((field.params || {}).visit_id || '');
    if(!s.selectedVisitId && originalId && s.vnRows.some(row => String(row && row._id || '') === originalId)) s.selectedVisitId = originalId;
  }, error => {
    s.vnLoading = false; s.vnRows = [];
    s.vnError = 'อ่าน Visit วันนี้ไม่สำเร็จ: ' + String((error && error.message) || error || 'ไม่ทราบสาเหตุ');
  });
};
s.emrVn = () => String(((field.params || {}).vn) || '');
s.vnOverridden = () => !!(s.manualContext && (field.params || {}).visit_id && String(s.manualContext.visit_id) !== String((field.params || {}).visit_id));
s.vnPickerTitle = () => s.manualMode() ? 'เลือกผู้ป่วยที่เปิด Visit วันนี้' : 'เลือก VN อีกช่องทาง (ค่าเริ่มต้นมาจาก EMR)';
s.vnPickerHint = () => s.manualMode() ? 'แสดงเฉพาะ Visit วันนี้ที่สถานะยังเปิดอยู่' : 'ล้างช่องเพื่อกลับไปใช้ VN เดิมจาก EMR';

/**
 * item_screen · onCreated — จอสั่งตรวจ/บริการ (ฟอร์ม CPOE Order App 6a927860422c1ca959829d26)
 *
 * แปลงจาก design/mockup/cpoe-item-order.tpl.html (C12) — กติกาทุกข้อยกมาจาก mockup ที่พี่ตรวจแล้ว
 * แก้พฤติกรรมที่นี่แล้วต้องแก้ mockup ด้วย ไม่งั้นต้นแบบกับของจริงจะเล่าคนละเรื่อง
 *
 * รอบนี้ (รอบ A) ครบ: segment · ความเร่งด่วน · สิทธิ์ · แถบ section · ติ๊กชีท · แถบกรอง X-ray · ค้นหา · ตะกร้า
 * รอบถัดไป (รอบ B): โหมด pick (หัตถการ/บริการอื่นๆ) · สิ่งส่งตรวจ · ยาที่เคยรับ · ประวัติการสั่ง · บันทึก/ส่งใบ
 *
 * 🔴 อ่าน patient context ผ่าน `field.params` ไม่ใช่ `field.formModel` — form_ui ที่มีแต่ vue-ui
 *    ตัด initData ทิ้งใน buildDataModel ⇒ ฟอร์มแม่ต้องส่ง context ทาง `params`
 * 🔴 เทมเพลตอ่านจาก `s.view` ที่ recompute() ทำไว้ให้ ไม่ใช่คำนวณสดในเทมเพลต —
 *    ติ๊กชีทมี 150-230 แถวต่อ section ถ้าเทมเพลตเรียกฟังก์ชันคำนวณ จะคำนวณซ้ำทุก binding ที่แตะมัน
 * 🔴 ห้ามให้เทมเพลตเขียนค่ากลับเข้า vueState (scope proxy ไม่มี set) ⇒ ทุกการเปลี่ยนค่าผ่าน method ที่นี่
 * 🔴 ทุก key ที่เทมเพลตอ้างต้องมีค่าตั้งแต่ตรงนี้ — ขาดตัวเดียว = error box ทั้ง widget
 */

const s = this.vueState;
const field = this;

const CATALOG_PROC = '6a9279a945ee4b7a59a1f049'; // cpoe-item-catalog
const HISTORY_PROC = '6a929f6d1eb7b2ece2b4f035'; // cpoe-item-history (ใบเก่าข้ามวิสิท)
const GET_PROC = '6a92a813c81f441a61358cf4'; // cpoe-item-get (อ่านใบเดิมกลับเข้าตะกร้า)
const SAVE_PROC = '6a71edd247075049ef0245af'; // cpoe-order-save (สร้าง/แก้ใบร่าง — ตัวเดียวกับจอสั่งยา)
const SEND_PROC = '6a757d1bf7bf7668d7673c63'; // cpoe-order-send (draft → sent)
const PRICE_PROC = '6a71214c650bf6eb42f45ce4'; // cpoe-price-calc (ตัวเดียวกับจอสั่งยา — ยอดที่หมอเห็นต้องเป็นชุดเดียวกับที่บันทึก)
const FORM_ITEM_MASTER = '6a594763d448dfc9d33e2c27'; // CPOE Item → zdata_master_item_order

