/* ══ แพทย์ผู้สั่ง ═════════════════════════════════════════════════════════
   🔴 คนกดบันทึกไม่ใช่คนสั่งเสมอไป — พยาบาล/ผู้ช่วยคีย์แทนได้ ⇒ ต้องเลือกได้
   ใช้ provider ตัวเดียวกับจอสั่งยา (`cpoe-doctor-list` กรอง roles LIKE 'DOCTOR' — พี่เคาะ 08-09)
   ⇒ สองจอเห็นรายชื่อชุดเดียวกันเสมอ · ไม่มี entity "รายชื่อหมอ" แยกให้ดูแลอีกชุด
   ⚠️ จอส่งแค่ id ไป — ชื่อที่ลงใบ process resolve จาก core_user เอง ไม่เชื่อ label จากจอ */
const DOCTOR_PROVIDER = '6a787a8a2294ae4131e6c268'; // cpoe-doctor-list (module_sql)

s.docList = [];
s.docLoading = false;
s.docId = '';

s.docLabel = (row) => {
	if (!row) return '';
	const name = [row.fname, row.lname].filter(Boolean).join(' ').trim() || row.username || '(ไม่มีชื่อ)';
	return row.license_no ? name + ' · ว.' + row.license_no : name;
};
s.setDoc = (v) => {
	s.docId = String(v || '');
};
s.loadDoctors = () => {
	s.docLoading = true;
	field.getFormRef().userState.crudGetAll(
		{ sdProvider: { providerId: DOCTOR_PROVIDER, providerType: 'SQL', params: {} }, totalEnable: false },
		(res) => {
			const rows = (res && res.data) || [];
			// เรียงที่จอ ไม่ใช่ที่ provider — ชื่อไทย/อังกฤษปนกัน localeCompare จัดได้ตรงกว่า sort ของ mongo
			s.docList = rows.slice().sort((a, b) => String(a.fname || '').localeCompare(String(b.fname || ''), 'th'));
			s.docLoading = false;
			/* ค่าเริ่มต้น = ตัวเอง ถ้าคนที่ล็อกอินอยู่เป็นหมอ (เคสปกติสุด: หมอสั่งตรวจเอง)
			   🔴 key ของ user คือ `user_id` (types/User.ts SdUserLogin) ไม่ใช่ `_id`/`id` —
			      เขียนผิดคือได้ค่าว่างแล้ว find ไม่เจอเสมอ ⇒ auto ไม่เคยทำงานเลยโดยไม่มี error ให้เห็น
			   provider cpoe-doctor-list select `core_user._id` เป็น `doctor_id` ⇒ เทียบกับ user_id ตรงๆ ได้ */
			if (!s.docId) {
				const u = (field.globalUserState && field.globalUserState.user) || {};
				const me = String(u.user_id || u._id || u.id || '');
				const hit = me && s.docList.find((r) => String(r.doctor_id) === me);
				if (hit) s.docId = String(hit.doctor_id);
			}
		},
		() => {
			s.docList = [];
			s.docLoading = false;
		}
	);
};

/* สิทธิ์ทั้งใบ — โครงเดียวกับที่ mockup ประกอบจาก visit.inscl_hos
   ไม่มีสิทธิ์ = คิดราคามาตรฐานทั้งใบ (ไม่ใช่บั๊ก — master ไม่มีแถวราคาตามสิทธิ์) */
s.insList = () => {
	const rows = (field.params || {}).inscl_hos;
	if (!Array.isArray(rows)) return [];
	return rows
		.filter((r) => r && r.inscl_item_main && r.inscl_item_main.value)
		.map((r) => ({
			main: r.inscl_item_main.value,
			sub: (r.inscl_item_sub && r.inscl_item_sub.value) || '',
			label: [r.inscl_item_main.label, r.inscl_item_sub && r.inscl_item_sub.label].filter(Boolean).join(' / '),
		}));
};
s.insCurrent = () => {
	const list = s.insList();
	return s.insIx >= 0 && list[s.insIx] ? list[s.insIx] : null;
};
/* ลำดับสิทธิ์ที่ส่งให้ price-calc — ตัวที่เลือกเป็น "สิทธิ์หลัก" แล้วต่อด้วยที่เหลือตามลำดับเดิม
   price-calc ไล่ทีละสิทธิ์ **ต่อรายการ** (พี่เคาะ 2026-09-20): เบิกไม่ได้ / ไม่เข้าเงื่อนไขจำกัดรายการ /
   ไม่มีแถวราคา ⇒ ตกไปสิทธิ์ถัดไป · หมดทุกสิทธิ์จึงเป็นชำระเอง
   insIx = -1 (เลือกชำระเองเอง) ⇒ ไม่ส่งสิทธิ์ไปเลย */
s.insChain = () => {
	const list = s.insList();
	if (!list.length || s.insIx < 0) return [];
	const head = list[s.insIx];
	const rest = list.filter((r, i) => i !== s.insIx);
	return (head ? [head].concat(rest) : list.slice()).map((r) => ({ main: r.main, sub: r.sub }));
};
/* เปลี่ยนสิทธิ์ได้เฉพาะ role INSURANCE (พี่เคาะ 2026-09-20) — คนอื่นเห็นสิทธิ์ที่ใช้อยู่ แต่แก้ไม่ได้
   ⚠️ ด่านหน้าจอเท่านั้น · ของจริงที่กันคือ cpoe-order-save ซึ่งคิดราคาใหม่จากลำดับสิทธิ์เสมอ */
const INSCL_ROLE = 'INSURANCE';
s.canSetIns = () => {
	const u = ((field.getFormRef() || {}).userState || {}).user || {};
	return Array.isArray(u.roles) && u.roles.indexOf(INSCL_ROLE) >= 0;
};
s.insLockHint = () => (s.canSetIns() ? '' : 'เปลี่ยนสิทธิ์ได้เฉพาะเจ้าหน้าที่สิทธิ์ (role INSURANCE)');
// สิทธิ์ที่ "ใช้จริง" ของบรรทัดนี้ — ว่าง = ไม่มีสิทธิ์ไหนใช้ได้กับรายการนี้ (ชำระเอง)
s.insUsedText = (l) => {
	const p = s.priceById[l && l.k];
	const u = p && p.inscl_used;
	return u ? u.main + (u.sub ? '/' + u.sub : '') : '';
};
s.setIns = (v) => {
	if (!s.canSetIns()) return;
	s.insIx = Number(v);
	s.repriceOnChange();   // สิทธิ์เปลี่ยน = ราคาทั้งใบเปลี่ยนได้ทุกบรรทัด
	repriceSheetSoon();    // ป้าย "จ่ายเอง" บนชีทก็ต้องคิดใหม่ตามสิทธิ์
};
/* บอกเหตุผลว่าทำไมยอด "เบิกได้" ออกมาเท่านี้ — 🔴 อ่านจากคำเตือนจริงที่ price-calc คืนมา
   ห้ามกลับไป hardcode ว่า "master ไม่มีแถวราคาสิทธิ์" อีก: วันนี้จริง (STD ล้วน 6,383 แถว)
   แต่วันที่มีคนเติมราคาสิทธิ์ ข้อความจะกลายเป็นคำโกหกที่ไม่มีใครสังเกต
   ⇒ process รู้เหตุผลจริงเสมอ (สิทธิ์เบิกไม่ได้ / รายการไม่อยู่ในเงื่อนไข / ไม่มีแถวราคา) */
s.insHint = () => {
	const ins = s.insCurrent();
	const who = ins ? 'สิทธิ์ ' + ins.main + '/' + (ins.sub || '-') : 'ไม่ได้เลือกสิทธิ์ — คิดราคามาตรฐานทั้งใบ';
	if (s.priceError) return who + ' · ' + s.priceError;
	if (!s.priceTotals) return who + ' · ยังไม่ได้คิดราคา';
	const why = {};
	s.cart.forEach((l) => {
		const p = s.priceById[l.k];
		(p && Array.isArray(p.alerts) ? p.alerts : []).forEach((a) => {
			if (a && a.message) why[a.message] = 1;
		});
	});
	const list = Object.keys(why);
	return list.length ? who + ' · ' + list.join(' · ') : who;
};

